// Improved application with security best practices
// Enhanced with error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent payload attacks

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

// Custom validation error formatter
const formatValidationErrors = (errors) => {
  return errors.array().map(err => ({
    field: err.path,
    message: err.msg,
  }));
};

// Sanitize user input by trimming and escaping
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return input.trim();
  }
  return input;
};

// ============================================
// ROUTES WITH VALIDATION & ERROR HANDLING
// ============================================

// Health check endpoint (no sensitive data exposed)
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Log error internally but don't expose details to client
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation for query params
app.get('/users', 
  [
    // Validate optional query parameters
    body('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          details: formatValidationErrors(errors) 
        });
      }

      // Sanitize query parameters
      const requestedId = req.query.id ? parseInt(sanitizeInput(req.query.id), 10) : null;
      const limit = req.query.limit ? parseInt(sanitizeInput(req.query.limit), 10) : 100;

      // Sample user data (in production, this would come from a database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter users if ID is provided
      let result = users;
      if (requestedId) {
        result = users.filter(user => user.id === requestedId);
      }

      // Apply limit
      result = result.slice(0, limit);

      res.json(result);
    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Example POST endpoint demonstrating comprehensive validation
app.post('/users',
  [
    // Validate required fields
    body('name')
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
      .trim()
      .escape(), // Escape HTML entities to prevent XSS

    body('email')
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Must be a valid email address')
      .normalizeEmail() // Normalize email (lowercase, trim)
      .isLength({ max: 255 }).withMessage('Email must not exceed 255 characters'),
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed', 
          details: formatValidationErrors(errors) 
        });
      }

      // Sanitized and validated data
      const { name, email } = req.body;

      // In production: Save to database
      const newUser = {
        id: Date.now(),
        name: sanitizeInput(name),
        email: email, // Already normalized by express-validator
      };

      res.status(201).json({ 
        message: 'User created successfully',
        user: newUser 
      });
    } catch (error) {
      console.error('Create user error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    // Only include stack trace in development
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

// Only start server if this file is run directly (not imported)
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

