// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      scriptSrc: ["'self'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-origin" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// 2. Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  // Use IP from X-Forwarded-For header if behind a proxy
  trustProxy: process.env.NODE_ENV === 'production',
});
app.use(limiter);

// 3. Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // Limit each IP to 5 login attempts per hour
  message: { error: 'Too many login attempts, please try again later.' },
});

// 4. Request body size limits
app.use(express.json({ limit: '10kb' })); // Body limit to prevent large payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. CORS configuration
const cors = require('cors');
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  optionsSuccessStatus: 204,
  maxAge: 86400, // 24 hours
};
app.use(cors(corsOptions));

// 6. Request sanitization - remove malicious characters
app.use((req, res, next) => {
  // Sanitize request body
  if (req.body && typeof req.body === 'object') {
    req.body = sanitizeObject(req.body);
  }
  // Sanitize query parameters
  if (req.query && typeof req.query === 'object') {
    req.query = sanitizeObject(req.query);
  }
  // Sanitize URL parameters
  if (req.params && typeof req.params === 'object') {
    req.params = sanitizeObject(req.params);
  }
  next();
});

/**
 * Recursively sanitize an object by removing potentially dangerous characters
 * @param {any} obj - Object to sanitize
 * @returns {any} Sanitized object
 */
function sanitizeObject(obj) {
  if (typeof obj === 'string') {
    return obj
      .replace(/[$]/g, '')  // Remove $ to prevent NoSQL injection
      .replace(/\.\./g, '') // Remove .. to prevent path traversal
      .trim();
  }
  if (Array.isArray(obj)) {
    return obj.map(sanitizeObject);
  }
  if (obj && typeof obj === 'object') {
    const sanitized = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        // Sanitize key to prevent prototype pollution
        const sanitizedKey = key.replace(/^$/, '').replace(/\./g, '');
        if (sanitizedKey && sanitizedKey !== '__proto__' && sanitizedKey !== 'constructor') {
          sanitized[sanitizedKey] = sanitizeObject(obj[key]);
        }
      }
    }
    return sanitized;
  }
  return obj;
}

// ============================================
// VALIDATION HELPERS
// ============================================

/**
 * Validation middleware to check for errors
 */
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

/**
 * Custom validation for IDs
 */
const validateId = (value) => {
  if (!Number.isInteger(value) || value <= 0) {
    throw new Error('ID must be a positive integer');
  }
  return true;
};

/**
 * Custom validation for email
 */
const validateEmail = (value) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(value)) {
    throw new Error('Invalid email format');
  }
  return true;
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint with more details
app.get('/health', (req, res) => {
  const healthCheck = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development',
    version: process.env.npm_package_version || '1.0.0',
  };

  res.status(200).json(healthCheck);
});

// Readiness check endpoint (for Kubernetes)
app.get('/ready', (req, res) => {
  // Add checks for external dependencies here (database, cache, etc.)
  const checks = {
    database: true, // Replace with actual DB check
    cache: true,    // Replace with actual cache check
  };

  const allHealthy = Object.values(checks).every(v => v === true);

  res.status(allHealthy ? 200 : 503).json({
    status: allHealthy ? 'ready' : 'not ready',
    checks,
  });
});

// Users endpoint with validated query parameters
app.get('/users', [
  // Optional query parameter validation
  body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  validate,
], (req, res) => {
  try {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: users.length,
      },
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Single user endpoint with parameter validation
app.get('/users/:id', [
  body('id').custom(validateId),
  validate,
], (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Simulate user lookup
    const user = { id: userId, name: 'Alice', email: 'alice@example.com' };

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    next(error);
  }
});

// Example POST endpoint with comprehensive validation
app.post('/users', [
  body('name')
    .trim()
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
