const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security Middleware
// ===================

// Set security HTTP headers
app.use(helmet());

// Rate limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Limit body size to 10kb
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
      timestamp: new Date().toISOString()
    });
  });

  next();
});

// Input validation and sanitization utilities
// ============================================

const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  // Remove potential XSS vectors
  return input
    .replace(/[<>]/g, '') // Remove < and >
    .trim();
};

const validateId = (value) => {
  const id = parseInt(value, 10);
  if (isNaN(id) || id < 1 || id > Number.MAX_SAFE_INTEGER) {
    throw new Error('Invalid ID format');
  }
  return id;
};

// Error handling utilities
// ========================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Routes
// ======

app.get('/health', asyncHandler(async (req, res) => {
  // Simple health check with database connection check could be added
  res.status(200).json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
}));

// In-memory user data (in production, use a database)
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', asyncHandler(async (req, res) => {
  // Add pagination support
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;

  // Validate pagination parameters
  if (page < 1 || limit < 1 || limit > 100) {
    throw new AppError('Invalid pagination parameters', 400);
  }

  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedUsers = users.slice(startIndex, endIndex);

  // Sanitize output to prevent data leakage
  const sanitizedUsers = paginatedUsers.map(user => ({
    id: user.id,
    name: sanitizeInput(user.name),
    email: sanitizeInput(user.email)
  }));

  res.status(200).json({
    status: 'success',
    data: sanitizedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
      totalPages: Math.ceil(users.length / limit)
    }
  });
}));

app.get('/users/:id', asyncHandler(async (req, res) => {
  // Validate and sanitize ID parameter
  const id = validateId(req.params.id);

  const user = users.find(u => u.id === id);

  if (!user) {
    throw new AppError('User not found', 404);
  }

  // Sanitize output
  res.status(200).json({
    status: 'success',
    data: {
      id: user.id,
      name: sanitizeInput(user.name),
      email: sanitizeInput(user.email)
    }
  });
}));

// POST endpoint example with validation
app.post('/users', 
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 100 })
      .withMessage('Name must be between 2 and 100 characters')
      .escape(),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Please provide a valid email')
      .normalizeEmail()
  ],
  asyncHandler(async (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      throw new AppError('Validation failed', 400);
    }

    const { name, email } = req.body;

    // Check for duplicate email
    if (users.some(u => u.email === email)) {
      throw new AppError('Email already exists', 409);
    }

    const newUser = {
      id: users.length + 1,
      name: sanitizeInput(name),
      email: sanitizeInput(email)
    };

    users.push(newUser);

    res.status(201).json({
      status: 'success',
      data: {
        id: newUser.id,
        name: newUser.name,
        email: newUser.email
      }
    });
  })
);

// 404 handler for undefined routes
app.use((req, res, next) => {
  next(new AppError(`Cannot find ${req.originalUrl} on this server`, 404));
});

// Global error handling middleware
app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error details (in production, use a proper logging service)
  console.error({
    error: err.message,
    stack: err.stack,
    statusCode: err.statusCode,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  // Handle specific error types
  if (err.name === 'ValidationError') {
    err.statusCode = 400;
    err.message = 'Invalid input data';
  }

  if (err.name === 'JsonWebTokenError') {
    err.statusCode = 401;
    err.message = 'Invalid token';
  }

  if (err.code === 'LIMIT_FILE_SIZE') {
    err.statusCode = 400;
    err.message = 'File too large';
  }

  res.status(err.statusCode).json({
    status: err.status,
    message: err.isOperational ? err.message : 'An error occurred',
    ...(isProduction ? {} : { stack: err.stack })
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Process terminated.');
    process.exit(0);
  });
});

process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err);
  process.exit(1);
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

