// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// Security headers using helmet
app.use(helmet());

// parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// ==================== INPUT VALIDATION UTILITIES ====================

/**
 * Validates email format
 * @param {string} email - Email to validate
 * @returns {boolean} - Whether email is valid
 */
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return typeof email === 'string' && emailRegex.test(email) && email.length <= 254;
}

/**
 * Validates and sanitizes string input
 * @param {any} input - Input to validate
 * @param {number} maxLength - Maximum allowed length
 * @returns {string|null} - Sanitized string or null if invalid
 */
function sanitizeString(input, maxLength = 255) {
  if (typeof input !== 'string') return null;
  if (input.length === 0 || input.length > maxLength) return null;
  // Basic XSS prevention - escape HTML entities
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

/**
 * Validates ID parameter
 * @param {any} id - ID to validate
 * @returns {number|null} - Validated number or null if invalid
 */
function validateId(id) {
  const parsed = parseInt(id, 10);
  if (isNaN(parsed) || parsed < 1 || parsed > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  return parsed;
}

// ==================== CUSTOM ERROR CLASS ====================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// ==================== ASYNC HANDLER WRAPPER ====================

/**
 * Wraps async route handlers to catch errors
 * @param {Function} fn - Async function to wrap
 * @returns {Function} - Express middleware with error handling
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ==================== ROUTES ====================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app, this would come from a database
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example route with input validation
app.get('/users/:id', asyncHandler(async (req, res, next) => {
  const userId = validateId(req.params.id);

  if (!userId) {
    return next(new AppError('Invalid user ID provided', 400));
  }

  // Simulated user lookup
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return next(new AppError('User not found', 404));
  }

  res.json(user);
}));

// Example POST route with input validation
app.post('/users', asyncHandler(async (req, res, next) => {
  const { name, email } = req.body;

  // Validate inputs
  const sanitizedName = sanitizeString(name, 100);
  if (!sanitizedName) {
    return next(new AppError('Valid name is required (max 100 characters)', 400));
  }

  if (!isValidEmail(email)) {
    return next(new AppError('Valid email is required', 400));
  }

  // Process validated input
  const newUser = {
    id: Date.now(), // In production, use proper ID generation
    name: sanitizedName,
    email,
  };

  res.status(201).json({
    status: 'success',
    data: { user: newUser },
  });
}));

// ==================== ERROR HANDLING ====================

// 404 handler for undefined routes
app.use((req, res, next) => {
  next(new AppError(`Cannot find ${req.method} ${req.originalUrl} on this server`, 404));
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Default values
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error in development
  if (process.env.NODE_ENV === 'development') {
    console.error('ERROR 💥:', err);
  }

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  // Handle specific error types
  if (err.name === 'SyntaxError' && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      status: 'fail',
      message: 'Invalid JSON in request body',
    });
  }

  // Operational errors: safe to send to client
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
    });
  }

  // Programming errors: don't leak details
  console.error('UNEXPECTED ERROR:', err);
  return res.status(500).json({
    status: 'error',
    message: isProduction ? 'Something went wrong' : err.message,
  });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

module.exports = app;

