// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ===================
// Security Middleware
// ===================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ===================
// Input Validation Utilities
// ===================

/**
 * Validates and sanitizes user ID parameter
 * @param {*} id - The ID to validate
 * @returns {Object} - { valid: boolean, value: number|null, error: string|null }
 */
function validateUserId(id) {
  if (id === undefined || id === null) {
    return { valid: false, value: null, error: 'ID is required' };
  }

  // Convert to number and validate
  const numId = parseInt(id, 10);

  if (isNaN(numId)) {
    return { valid: false, value: null, error: 'ID must be a number' };
  }

  if (numId <= 0) {
    return { valid: false, value: null, error: 'ID must be a positive number' };
  }

  if (numId > Number.MAX_SAFE_INTEGER) {
    return { valid: false, value: null, error: 'ID is too large' };
  }

  return { valid: true, value: numId, error: null };
}

/**
 * Validates email format
 * @param {string} email - The email to validate
 * @returns {Object} - { valid: boolean, error: string|null }
 */
function validateEmail(email) {
  if (!email || typeof email !== 'string') {
    return { valid: false, error: 'Email is required' };
  }

  // Basic email format validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!emailRegex.test(email)) {
    return { valid: false, error: 'Invalid email format' };
  }

  if (email.length > 254) {
    return { valid: false, error: 'Email is too long' };
  }

  return { valid: true, error: null };
}

/**
 * Validates name input
 * @param {string} name - The name to validate
 * @returns {Object} - { valid: boolean, error: string|null }
 */
function validateName(name) {
  if (!name || typeof name !== 'string') {
    return { valid: false, error: 'Name is required' };
  }

  // Trim whitespace
  const trimmedName = name.trim();

  if (trimmedName.length === 0) {
    return { valid: false, error: 'Name cannot be empty' };
  }

  if (trimmedName.length > 100) {
    return { valid: false, error: 'Name is too long (max 100 characters)' };
  }

  // Only allow alphanumeric characters, spaces, hyphens, and apostrophes
  const nameRegex = /^[a-zA-Z0-9\s\-']+$/;
  if (!nameRegex.test(trimmedName)) {
    return { valid: false, error: 'Name contains invalid characters' };
  }

  return { valid: true, error: null };
}

// ===================
// Routes
// ===================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example route with parameter validation
app.get('/users/:id', (req, res) => {
  const validation = validateUserId(req.params.id);

  if (!validation.valid) {
    return res.status(400).json({ error: validation.error });
  }

  // In a real app, fetch user from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === validation.value);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  res.json(user);
});

// Example POST route with input validation
app.post('/users', (req, res) => {
  const { name, email } = req.body;

  // Validate inputs
  const nameValidation = validateName(name);
  if (!nameValidation.valid) {
    return res.status(400).json({ error: nameValidation.error });
  }

  const emailValidation = validateEmail(email);
  if (!emailValidation.valid) {
    return res.status(400).json({ error: emailValidation.error });
  }

  // Sanitize inputs (escape HTML to prevent XSS)
  const sanitizedName = name.trim();
  const sanitizedEmail = email.toLowerCase().trim();

  // In a real app, save to database
  const newUser = {
    id: Date.now(),
    name: sanitizedName,
    email: sanitizedEmail,
  };

  res.status(201).json(newUser);
});

// ===================
// Error Handling
// ===================

// 404 handler for unknown routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error internally (don't expose to client)
  console.error('Error:', err);

  // Handle specific error types
  if (err.type === 'entity.too.large') {
    return res.status(413).json({ error: 'Request payload too large' });
  }

  if (err.name === 'SyntaxError') {
    return res.status(400).json({ error: 'Invalid JSON' });
  }

  // Generic error response (don't leak internal details)
  res.status(500).json({ error: 'Internal Server Error' });
});

// ===================
// Server Startup
// ===================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

